/*
 * A055938  Integers not generated by b(n) = b(floor(n/2)) + n (complement of
 *          A005187).
 * https://oeis.org/A055938
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nice, nonn
 * Formula:   a(n) = integers not generated by the recurrence b(0)=0,
 *            b(k)=b(floor(k/2)) + k (complement of A005187)
 * Range:     u8 n <= 127, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stddef.h>
#include <stdlib.h>
#include <string.h>

/* Static storage for the recurrence values (b) */
static seq_t *b        = NULL;
static size_t b_len    = 0, b_cap   = 0;

/* Static storage for a bitvector marking which integers are in b */
static bool *present       = NULL;
static size_t present_cap  = 0;

/* Static storage for the missing values (a) */
static seq_t *missing      = NULL;
static size_t missing_len  = 0, missing_cap = 0;

/* Next integer to test for membership in b */
static idx_t next_missing_candidate = 1;

/* Helper: ensure that array 'b' can hold at least 'need' elements. */
static void grow_b(size_t need)
{
    if (b_cap == 0) b_cap = 16;
    while (b_cap < need) b_cap <<= 1;
    seq_t *tmp = (seq_t *)realloc(b, b_cap * sizeof(seq_t));
    if (!tmp) exit(1);
    b = tmp;
}

/* Helper: ensure that array 'missing' can hold at least 'need' elements. */
static void grow_missing(size_t need)
{
    if (missing_cap == 0) missing_cap = 64;
    while (missing_cap < need) missing_cap <<= 1;
    seq_t *tmp = (seq_t *)realloc(missing, missing_cap * sizeof(seq_t));
    if (!tmp) exit(1);
    missing = tmp;
}

/* Helper: ensure that the present bitvector can index at least 't'. */
static void ensure_present_size(seq_t t)
{
    size_t tt = (size_t)t;
    if (tt < present_cap) return;
    size_t new_cap = present_cap ? present_cap : 1;
    while (new_cap <= tt) new_cap <<= 1;
    bool *tmp = (bool *)realloc(present, new_cap * sizeof(bool));
    if (!tmp) exit(1);
    memset(tmp + present_cap, 0, (new_cap - present_cap) * sizeof(bool));
    present   = tmp;
    present_cap = new_cap;
}

/* Compute b-values until the last computed value is >= target. */
static void ensure_b_up_to_value(seq_t target)
{
    /* make sure the bitvector covers the target index */
    ensure_present_size(target);

    /* initialise b if empty */
    if (b_len == 0) {
        grow_b(1);
        b[0] = 0;
        b_len = 1;
        ensure_present_size(0);
        present[0] = true;
    }

    /* grow b until last value >= target */
    while ((seq_t)b[b_len - 1] < target) {
        size_t next_index = b_len;                 /* next index to compute */
        seq_t val = b[next_index / 2] + (seq_t)next_index;  /* recurrence */
        grow_b(b_len + 1);
        b[b_len++] = val;
        ensure_present_size(val);
        present[(size_t)val] = true;
    }
}

/* The required OEIS function */
seq_t a(idx_t n)
{
    if (n == 0)          /* not defined for offset 0; return placeholder */
        return 0;

    /* Produce missing values until we have at least n of them. */
    while (missing_len < (size_t)n) {
        seq_t cur = (seq_t)next_missing_candidate;
        ensure_b_up_to_value(cur);                   /* mark all b <= cur */
        if (!present[(size_t)cur]) {                 /* cur is not in b */
            if (missing_len == missing_cap)
                grow_missing(missing_len + 1);
            missing[missing_len++] = cur;
        }
        ++next_missing_candidate;
    }

    return missing[(size_t)n - 1];
}
